 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])

    # Palette is a short run of identical rows containing several colors.
    # Ignore zeros while identifying the row pattern, but require the same
    # occupied columns and colors on consecutive rows.
    palette = None
    best_len = 0
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v]
        if len(cols) < 2 or len({grid[r][c] for c in cols}) < 2:
            continue
        end = r + 1
        while end < h and [c for c, v in enumerate(grid[end]) if v] == cols \
                and [grid[end][c] for c in cols] == [grid[r][c] for c in cols]:
            end += 1
        if end - r > best_len:
            best_len = end - r
            palette = {(rr, c) for rr in range(r, end) for c in cols}
            colors = [grid[r][c] for c in cols]
    if palette is None:
        raise ValueError('palette not found')

    # The color-1 template is the largest 4-connected component of 1s,
    # excluding the palette itself.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 1 and (r, c) not in palette}
    components = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                if p in remaining:
                    remaining.remove(p)
                    comp.add(p)
                    q.append(p)
        components.append(comp)
    if not components:
        raise ValueError('template shape not found')
    shape_abs = max(components, key=len)
    top = min(r for r, c in shape_abs)
    left = min(c for r, c in shape_abs)
    shape = {(r-top, c-left) for r, c in shape_abs}
    shape_h = max(r for r, c in shape) + 1
    base_index = colors.index(1)

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        new_top = top + (i - base_index) * shape_h
        for dr, dc in shape:
            rr, cc = new_top + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
